// ═══════════════════════════════════════════════════════════════════════════
// pdf-font-ro.js — Font Unicode (DejaVu Sans, subset RO) pentru jsPDF.
// Rezolva diacriticele romanesti in PDF (helvetica jsPDF nu are glife pentru
// a/i/s/t cu diacritice -> aparea text corupt). Aliaseaza helvetica->DejaVu,
// pastreaza diacriticele in _pdfSafe, si curata emoji din .text() (DejaVu nu
// are emoji). Numerele trec automat la String (fixeaza erori 'must be string').
// Licenta font: DejaVu Fonts (Bitstream Vera derivat, redistribuibil).
// ═══════════════════════════════════════════════════════════════════════════
(function () {
  'use strict';
  var FONT_R = "";
  var FONT_B = "";

  var KEEP = /[^\x09\x0A\x0D\x20-\x7E\u00A0-\u024F\u2013\u2014\u2018\u2019\u201C\u201D\u201E\u2022\u2026\u20AC\u2192\u2713\u00AB\u00BB]/g;
  function _uniSafe(t) {
    if (t === null || t === undefined) return '';
    return String(t)
      .replace(/[\u{1F000}-\u{1FFFF}]/gu, '')   // emoji
      .replace(/[\uFE00-\uFE0F\u200D]/g, '')     // variation selectors / ZWJ
      .replace(/[\u2600-\u26FF]/g, '')           // misc symbols (emoji-ish)
      .replace(KEEP, '');                          // pastreaza Latin + diacritice + cateva simboluri
  }

  // _pdfSafe care PASTREAZA diacriticele (font le suporta acum), curata doar emoji.
  function _pdfSafeUni(t) {
    if (t === null || t === undefined) return '—';
    return _uniSafe(t).trim() || '—';
  }

  function _register(J) {
    if (!J || J.__roFont) return;
    J.__roFont = true;
    J.API.events.push(['addFonts', function () {
      try {
        this.addFileToVFS('DejaVuRO.ttf', FONT_R); this.addFont('DejaVuRO.ttf', 'DejaVu', 'normal');
        this.addFileToVFS('DejaVuRO-Bold.ttf', FONT_B); this.addFont('DejaVuRO-Bold.ttf', 'DejaVu', 'bold');
      } catch (e) { }
    }]);
    var _setFont = J.API.setFont;
    J.API.setFont = function (font, style, weight) {
      if (/^(helvetica|times|courier|arial)$/i.test(font || '')) font = 'DejaVu';
      var st = (style === 'italic' || style === 'bolditalic') ? (style === 'bolditalic' ? 'bold' : 'normal') : style;
      try { return _setFont.call(this, font, st, weight); }
      catch (e) { try { return _setFont.call(this, 'DejaVu', 'normal'); } catch (e2) { } }
    };
    // NU atingem J.API.text (jsPDF defineste text pe instanta, nu pe API).
    // Inveliim text-ul instantei la evenimentul 'initialized' (this = instanta, text real).
    J.API.events.push(['initialized', function () {
      try {
        var inst = this;
        if (typeof inst.text === 'function' && !inst.text.__roWrap) {
          var _t = inst.text;
          inst.text = function (text, x, y, opts, transform) {
            try {
              if (Array.isArray(text)) text = text.map(_uniSafe);
              else text = _uniSafe(text);
            } catch (e) { }
            return _t.call(this, text, x, y, opts, transform);
          };
          inst.text.__roWrap = true;
        }
        // Alias setFont la nivel de instanta (helvetica/times/courier -> DejaVu)
        if (typeof inst.setFont === 'function' && !inst.setFont.__roWrap) {
          var _sf = inst.setFont;
          inst.setFont = function (font, style, weight) {
            if (/^(helvetica|times|courier|arial)$/i.test(font || '')) font = 'DejaVu';
            var st = (style === 'italic' || style === 'bolditalic') ? (style === 'bolditalic' ? 'bold' : 'normal') : style;
            try { return _sf.call(this, font, st, weight); }
            catch (e) { try { return _sf.call(this, 'DejaVu', 'normal'); } catch (e2) { } }
          };
          inst.setFont.__roWrap = true;
        }
        // Font implicit = DejaVu (text fara setFont explicit foloseste tot DejaVu, nu helvetica)
        try { inst.setFont('DejaVu', 'normal'); } catch (e) { }
      } catch (e) { }
    }]);
  }

  function _init() {
    var J = window.jspdf && window.jspdf.jsPDF;
    if (J) { _register(J); }
    // override global _pdfSafe ca sa pastreze diacriticele (S2 din studii il foloseste)
    try { window._pdfSafe = _pdfSafeUni; } catch (e) { }
    return !!J;
  }
  if (!_init()) {
    var n = 0, iv = setInterval(function () { if (_init() || ++n > 60) clearInterval(iv); }, 150);
  }
  // re-aplica override-ul _pdfSafe periodic (alte scripturi il pot redefini la load)
  var m = 0, iv2 = setInterval(function () { try { window._pdfSafe = _pdfSafeUni; } catch (e) { } if (++m > 30) clearInterval(iv2); }, 300);
})();
